859|<script>
860|const dropZone = document.getElementById('dropZone');
861|const fileInput = document.getElementById('fileInput');
862|const fileNameDiv = document.getElementById('fileName');
863|const processBtn = document.getElementById('processBtn');
864|const resultsSection = document.getElementById('resultsSection');
865|const docCountSpan = document.getElementById('docCount');
866|
867|let selectedFile = null;
868|
869|dropZone.addEventListener('click', () => fileInput.click());
870|
871|fileInput.addEventListener('change', () => {
872|  const files = fileInput.files;
873|  if (files.length > 0) {
874|    selectedFile = files[0];
875|    if (files.length === 1) {
876|      fileNameDiv.textContent = selectedFile.name + ' (' + Math.round(selectedFile.size/1024) + ' KB)';
877|    } else {
878|      fileNameDiv.textContent = files.length + ' files selected';
879|    }
880|    processBtn.disabled = false;
881|    processBtn.textContent = 'Process ' + files.length + ' file(s)';
882|  } else {
883|    fileNameDiv.textContent = 'No file selected';
884|    processBtn.disabled = true;
885|    processBtn.textContent = 'Upload & Process';
886|  }
887|});
888|
889|processBtn.addEventListener('click', async () => {
890|  if (!selectedFile) return;
891|
892|  processBtn.disabled = true;
893|  processBtn.textContent = 'Processing...';
894|  resultsSection.style.display = 'none';
895|  const mappingBody = document.getElementById('mappingBody');
896|  const resultContent = document.getElementById('resultContent');
897|  const resultTitle = document.getElementById('resultTitle');
898|  const resultStatus = document.getElementById('resultStatus');
899|
900|  const formData = new FormData();
901|  formData.append('file', selectedFile);
902|
903|  try {
904|    const res = await fetch('/upload', {method: 'POST', body: formData});
905|    const data = await res.json();
906|    
907|    // Re-enable button
908|    processBtn.disabled = false;
909|    processBtn.textContent = 'Upload & Process';
910|
911|    if (data.error) {
912|      resultTitle.textContent = 'Processing Error';
913|      resultStatus.className = 'status-badge status-error';
914|      resultStatus.textContent = '✗ Failed';
915|      resultContent.innerHTML = '<div class="error-msg">Error: ' + data.error + '</div>';
916|      resultsSection.style.display = 'block';
917|    } else {
918|      resultTitle.textContent = data.original_filename || 'Document Processed';
919|      resultStatus.className = 'status-badge status-success';
920|      resultStatus.textContent = '✓ Complete';
921|      
922|      // File info table
923|      document.getElementById('resultFilename').textContent = data.original_filename || 'N/A';
924|      document.getElementById('resultUploadPath').textContent = data.file_path || 'See uploads dir';
925|      document.getElementById('resultRedactions').textContent = data.total_redactions;
926|      document.getElementById('resultCategories').textContent = Object.keys(data.category_counts || {}).join(', ');
927|      document.getElementById('resultSafePath').textContent = data.safe_url || 'N/A';
928|      document.getElementById('resultMapPath').textContent = 'Redaction map stored at: ' + (data.map_path || 'data/redaction_maps/');
929|
930|      // Redaction summary badges
931|      const categoryGroups = {
932|        'PII': ['SSN', 'EMAIL', 'PHONE', 'CREDIT_CARD', 'BANK_ACCOUNT'],
933|        'BUSINESS': ['PRODUCT_NAME', 'COMPANY_NAME', 'DIRECTOR_NAME', 'QUOTATION_ID'],
934|        'FINANCIAL': ['COST_VALUE']
935|      };
936|      
937|      let badgesHtml = '';
938|      for (const [cat, count] of Object.entries(data.category_counts || {})) {
939|        let badgeClass = '';
940|        if (categoryGroups.PII.includes(cat)) badgeClass = 'sensitive';
941|        else if (categoryGroups.BUSINESS.includes(cat)) badgeClass = 'business';
942|        else if (categoryGroups.FINANCIAL.includes(cat)) badgeClass = 'financial';
943|        
944|        badgesHtml += '<span class="redaction-badge ' + badgeClass + '">' + cat + ': ' + count + '</span>';
945|      }
946|      document.getElementById('redactionSummary').innerHTML = badgesHtml;
947|
948|      // Fetch safe content and build result
949|      try {
950|        const safeRes = await fetch('/documents/' + data.document_id + '/safe');
951|        const safeData = await safeRes.json();
952|        
953|        let safeText = safeData.all_text || 'No text extracted';
954|        safeText = safeText.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
955|        // Highlight variables
956|        safeText = safeText.replace(/\{[A-Z]+_\d+\}/g, '<span class="variable-highlight">$&</span>');
957|        
958|        resultContent.textContent = safeText;
959|        
960|      } catch(e) {
961|        resultContent.innerHTML = '<div class="error-msg">Could not load safe document content</div>';
962|      }
963|
964|      // Fetch redaction mapping from separate endpoint (inside try block, with data)
965|      try {
966|        const mapRes = await fetch('/documents/' + data.document_id + '/map');
967|        const mapData = await mapRes.json();
968|        
969|        let mappingHtml = '';
970|        const mapping = mapData.full_map || {};
971|        for (const [varName, info] of Object.entries(mapping)) {
972|          let badgeClass = '';
973|          if (['SSN', 'EMAIL', 'PHONE', 'CREDIT_CARD', 'BANK_ACCOUNT'].includes(info.category)) badgeClass = 'sensitive';
974|          else if (['PRODUCT_NAME', 'COMPANY_NAME', 'DIRECTOR_NAME'].includes(info.category)) badgeClass = 'business';
975|          else if (['QUOTATION_ID'].includes(info.category)) badgeClass = 'sensitive';
976|          else if (['COST_VALUE'].includes(info.category)) badgeClass = 'financial';
977|          else badgeClass = 'sensitive';
978|          
979|          const safeValue = info.original.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
980|          mappingHtml += '<tr><td>' + varName + '</td><td style="font-family: monospace;">' + safeValue + '</td>';
981|          mappingHtml += '<td><span class="redaction-badge ' + badgeClass + '">' + info.category + '</span><br><small style="color: var(--text-secondary);">' + info.group + '</small></td></tr>';
982|        }
983|        mappingBody.innerHTML = mappingHtml || '<tr><td colspan="3">No variables mapped</td></tr>';
984|      } catch(e2) {
985|        mappingBody.innerHTML = '<tr><td colspan="3">Mapping unavailable</td></tr>';
986|      }
987|      
988|      resultsSection.style.display = 'block';
989|    }
990|    
991|    // Reset form
992|    fileNameDiv.textContent = 'Ready to upload another file';
993|    fileInput.value = '';
994|    await loadDocs();
995|    
996|  } catch(e) {
997|    processBtn.disabled = false;
998|    processBtn.textContent = 'Upload & Process';
999|    resultTitle.textContent = 'Error';
1000|    resultStatus.className = 'status-badge status-error';
1001|    resultStatus.textContent = '✗ Failed';
1002|    resultContent.innerHTML = '<div class="error-msg">Error: ' + e.message + '</div>';
1003|    resultsSection.style.display = 'block';
1004|  }
1005|});
