1007|async function resetServer() {
1008|  if (!confirm('Restart the server now? This picks up any changes made to doc_reader_onefile.py since it was last started. The page will reload automatically in a few seconds.')) {
1009|    return;
1010|  }
1011|  try {
1012|    await fetch('/restart', { method: 'POST' });
1013|  } catch (e) {
1014|    // The connection is expected to drop as the old process exits — this is normal, not an error.
1015|  }
1016|  const statusEl = document.createElement('div');
1017|  statusEl.textContent = 'Restarting server, please wait…';
1018|  statusEl.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);background:#1a2332;color:#fff;padding:12px 24px;border-radius:8px;z-index:9999;font-size:14px;';
1019|  document.body.appendChild(statusEl);
1020|
1021|  let attempts = 0;
1022|  const tryReload = async () => {
1023|    attempts++;
1024|    try {
1025|      const res = await fetch('/health', { cache: 'no-store' });
1026|      if (res.ok) { location.reload(); return; }
1027|    } catch (e) { /* server still coming back up, keep waiting */ }
1028|    if (attempts < 20) { setTimeout(tryReload, 500); }
1029|    else { statusEl.textContent = 'Still restarting… you can also refresh manually.'; }
1030|  };
1031|  setTimeout(tryReload, 2000);
1032|}
