1034|async function loadDocs() {
1035|  try {
1036|    const res = await fetch('/documents');
1037|    const data = await res.json();
1038|    const docs = data.documents || [];
1039|    const docsList = document.getElementById('docsList');
1040|    docCountSpan.textContent = '(' + docs.length + ')';
