196|class EnhancedRedactionEngine:
197|    """Enterprise-grade data anonymization engine with business-sensitive detection."""
198|    
199|    def __init__(self, settings=None):
200|        # Build flat pattern list from policy
201|        self.categories = OrderedDict()
202|        self.settings = settings if settings else get_default_settings()
203|        self._build_patterns()
204|    
205|    def _build_patterns(self):
206|        """Build regex patterns from security policy, respecting user settings."""
207|        for group_name, group_settings in self.settings.get("categories", {}).items():
208|            if not group_settings.get("enabled", True):
209|                continue
210|            categories = SECURITY_POLICY.get(group_name, {})
211|            for cat_key, cat_info in categories.items():
212|                # Check if this category is enabled in settings
213|                sub_settings = group_settings.get("subcategories", {}).get(cat_key, {})
214|                if not sub_settings.get("enabled", True):
215|                    continue
216|                patterns = cat_info.get('patterns', [cat_info.get('pattern', '')])
217|                for p in patterns:
218|                    if p:
219|                        if cat_key not in self.categories:
220|                            self.categories[cat_key] = []
221|                        self.categories[cat_key].append((p, cat_info))
222|
223|        # Add custom categories
224|        for custom in self.settings.get("custom", []):
225|            cat_key = custom.get("name", "CUSTOM")
226|            if not custom.get("enabled", True):
227|                continue
228|            pattern_str = custom.get("pattern", "")
229|            if pattern_str:
230|                cat_info = {
231|                    "description": custom.get("description", cat_key),
232|                    "dummy_prefix": custom.get("dummy_prefix", cat_key),
233|                    "critical": custom.get("critical", False),
234|                    "category": custom.get("category", "CUSTOM")
235|                }
236|                if cat_key not in self.categories:
237|                    self.categories[cat_key] = []
238|                self.categories[cat_key].append((pattern_str, cat_info))
239|    
240|    def redact(self, text):
241|        """Perform redaction with reversible mapping.
242|        
243|        Critical fix: Process categories in priority order (PII first, then business)
244|        to ensure overlapping patterns don't leak. Use position-based replacement
245|        to handle exact span replacement.
246|        """
247|        redactions = []
248|        category_counts = {}
249|        
250|        # Define priority order - PII critical data first
251|        priority_order = ['SSN', 'EMAIL', 'CREDIT_CARD', 'BANK_ACCOUNT', 'PHONE',
252|                         'QUOTATION_ID', 'COST_VALUE',
253|                         'COMPANY_NAME', 'PRODUCT_NAME', 'DIRECTOR_NAME']
254|        
255|        # Collect all matches across all categories
256|        all_matches = []
257|        for category in priority_order:
258|            if category not in self.categories:
259|                continue
260|            for pattern, cat_info in self.categories[category]:
261|                for match in re.finditer(pattern, text, re.IGNORECASE):
262|                    all_matches.append({
263|                        'start': match.start(),
264|                        'end': match.end(),
265|                        'text': match.group(),
266|                        'category': category,
267|                        'cat_info': cat_info
268|                    })
269|        
270|        # Sort by position, then by length (longer matches first for overlapping)
271|        all_matches.sort(key=lambda m: (m['start'], -m['end']))
272|        
273|        # Process matches, handling overlaps by position
274|        redaction_map = []
275|        last_end = 0
276|        result_parts = []
277|        counter = 0
278|        
279|        for match in all_matches:
280|            # Skip if this match overlaps with a previously processed match
281|            if match['start'] < last_end:
282|                continue
283|            
284|            # Add text before the match
285|            result_parts.append(text[last_end:match['start']])
286|            
287|            # Count by category
288|            category = match['category']
289|            category_counts[category] = category_counts.get(category, 0) + 1
290|            counter = category_counts[category]
291|            
292|            # Get dummy prefix
293|            dummy_prefix = match['cat_info'].get('dummy_prefix', category)
294|            var_name = f"{{{dummy_prefix}_{counter}}}"
295|            
296|            redaction_map.append({
297|                'variable': var_name,
298|                'original': match['text'].strip(),
299|                'category': category,
300|                'group': match['cat_info'].get('description', category),
301|                'position': match['start']
302|            })
303|            
304|            result_parts.append(var_name)
305|            last_end = match['end']
306|            redactions.append({
307|                'category': category,
308|                'variable': var_name,
309|                'original': match['text'].strip(),
310|                'length': len(match['text'])
311|            })
312|        
313|        # Add remaining text
314|        result_parts.append(text[last_end:])
315|        safe_text = ''.join(result_parts)
316|        
317|        return safe_text, redaction_map, category_counts, redactions
